import { IHikingMenuAssigneeUser } from '../../../@types/hikingMenu.types';

interface IProductForPrintDTO {
  food_act_name: string; // "Обед",
  is_one: string; // "1",
  is_force: string; // "0",
  recipe_name: string; // "Борщ с заправкой Maggi (субл)",
  d1: string; // "2025-09-01 22:12:00",
  uname: null | string; // null,
  usurname: null | string; // null,
  uphoto: null | string; // null,
  uid: null | string; // null,
  original_id_product: string; // "135",
  original_name: string; // "Капуста белокочанная сушеная",
  replace_rate: null | string; // null,
  name: string; // "Капуста белокочанная сушеная",
  id_product: string; // "135",
  amount: string; // "10.0000",
  protein_per_gram: string; // "0.15",
  carbohydrates_per_gram: string; // "0.48",
  fat_per_gram: string; // "0.01",
  energy_per_gram: string; // "2.7800",
  is_optimize: string; // "0",

  protein: number; // 1.5,
  carbohydrates: number; // 4.8,
  fat: number; // 0.1,
  energy: number; // 27.8
}
export interface IProductForPrint {
  name: string;
  ex?: { id: number; name: string; rate: number };
  user: IHikingMenuAssigneeUser | null;
  actName: string;
  recipeName: string;
  date: Date;
  amount: number;
  idProduct: number;
  proteins: number;
  fats: number;
  carbs: number;
  energy: number;
  isForced: boolean;
}

export function mapStickerToFront(backModel: IProductForPrintDTO): IProductForPrint {
  return {
    user: backModel?.uid
      ? {
          id: +backModel.uid!,
          name: [backModel?.uname, backModel?.usurname].join(' '),
          photo: backModel?.uphoto ?? '',
        }
      : null,
    ex:
      backModel.id_product === backModel.original_id_product
        ? undefined
        : {
            id: +backModel.original_id_product,
            name: backModel.original_name,
            rate: +backModel.replace_rate!,
          },
    actName: backModel?.food_act_name,
    recipeName: backModel?.recipe_name,
    name: backModel?.name,
    date: new Date(Date.parse(backModel?.d1)),
    amount: +backModel?.amount,
    idProduct: +backModel?.id_product,
    proteins: +backModel.protein,
    fats: +backModel.fat,
    carbs: +backModel.carbohydrates,
    energy: +backModel.protein,
    isForced: +backModel.is_force === 1,
  };
}

export default {};
